-- 112_consent_templates_seed.sql
--
-- Consent templates (14 rows) from the previous database, exported 2026-10-08.
-- They are not seeded by any SQL/v1 file. Without them no staff member can sign onboarding consent, so no
-- staff account (including the super admin) can become active.
--
-- Not copied (need a decision): the tDCS/tVNS dosing and device tables, whose rows point at
-- neuromod_conditions by UUID (different in every database), and the per-clinic pricing and
-- cancellation policy, which point at clinics that do not exist yet.
--
-- Safe to re-run: ON CONFLICT DO NOTHING (rows already present are kept, not overwritten).
-- Each table is loaded with jsonb_populate_recordset, so columns that exist only
-- in one database are ignored or defaulted instead of failing.

BEGIN;

-- consent_templates: 14 rows
INSERT INTO reference.consent_templates
SELECT * FROM jsonb_populate_recordset(NULL::reference.consent_templates, $json$[{"template_id": "e07f3107-cf47-4de3-9f13-cbe655b3a33e", "consent_type": "patient_onboarding", "version": 1, "title": "Patient Onboarding Consent", "content": "I, the undersigned patient, consent to enroll in the Anava Clinic neurological care program. I understand that my personal and medical information will be collected and used for the purpose of providing neurological assessment, treatment planning, and follow-up care. I consent to the collection of EEG data, administration of standardized psychological rating scales (PRS), and other clinical assessments as determined by the clinical team. I understand that a Receptionist will witness this consent signing. I understand that my records will be retained permanently as required by medical record-keeping regulations. I have the right to exit the program at any time.", "content_hash": "7dca15955f7c40de9cfbe1b8075d036f865678542b20ba86c6f04c234eebd8b9", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:24:10.091531+00:00", "role": null}, {"template_id": "54fefb40-1353-4a4f-8066-a196687ba882", "consent_type": "patient_clinic_exit", "version": 1, "title": "Patient Clinic Exit Consent", "content": "I, the undersigned patient, voluntarily consent to discharge from Anava Clinic. I understand that my clinical records will be archived permanently in read-only status. I acknowledge that the treatment program may be incomplete and that I am exiting at my own discretion. I understand that re-joining the clinic in the future will require a new registration process.", "content_hash": "b9ad976f9f01ec66b599389e027b432537a8413177259a87c930956dc8df374d", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:24:10.091531+00:00", "role": null}, {"template_id": "469a1581-7bbf-4789-8705-1829a7ecde64", "consent_type": "patient_clinic_transfer", "version": 1, "title": "Patient Clinic Transfer Consent", "content": "I, the undersigned patient, consent to the transfer of my complete clinical records from [FROM_CLINIC] to [TO_CLINIC]. I understand this transfer is being facilitated due to the closure of [FROM_CLINIC]. I consent to the allocation of a new Doctor at the receiving clinic. I understand that my treatment will continue without interruption from where it was paused. My records at the original clinic will be retained permanently in read-only status.", "content_hash": "3780790a5dec17f62afbbd730b2541f60db1d75722d5fdfb68307a46d711074d", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:24:10.091531+00:00", "role": null}, {"template_id": "7ba0de87-5967-4785-a3ee-a3fbba7cd6f9", "consent_type": "patient_relocation_transfer", "version": 1, "title": "Patient Relocation Transfer Consent", "content": "I, the undersigned patient, consent to the transfer of my complete clinical records from [FROM_CLINIC] to [TO_CLINIC] due to my permanent relocation to a new region. I understand that this is not an exit from the Anava care program — my treatment will continue at the new clinic. I consent to the auto-allocation of a new Doctor at the receiving clinic. Any active appointment block will resume from its current position without restart. My records at the original clinic will be retained permanently in read-only status.", "content_hash": "bab88631415d8449f3d674259144776982a70f4dd48a60ed14583171a439b846", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:24:10.091531+00:00", "role": null}, {"template_id": "b772c0fe-a0f6-41e3-bdca-3c18b5035c0c", "consent_type": "staff_offboarding", "version": 1, "title": "Staff Offboarding Consent", "content": "I, the undersigned staff member, acknowledge the termination of my association with [CLINIC_NAME] as [ROLE]. I understand that my access to the Anava platform will be revoked immediately upon signing this consent. I confirm that I have no outstanding patient responsibilities and that all pending clinical documentation has been completed. My employment records will be retained permanently as required by regulation.", "content_hash": "3aa5c8a91bbe70d70a402ed097fd78d61b02408cf35ce3bd8de93b5651b88c6e", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:24:10.091531+00:00", "role": null}, {"template_id": "84044ccd-a292-4497-9e7a-0c6a1855cc48", "consent_type": "clinic_join_anava", "version": 1, "title": "Partner Clinic — Join Anava Network Consent", "content": "We, the authorized representatives of [PARTNER_CLINIC_NAME], consent to joining the Anava Clinic partner network operated by Mana Health Sciences Group. We agree to operate under the Anava clinical protocols, patient care standards, and data governance framework. We acknowledge that Regional Admin oversight applies to our clinic operations and staff. We understand the obligations regarding patient record retention and data security.", "content_hash": "0fd45f5c4e64cfcbbe1511156208f3929d0e3111962ae261428cf6c61e888f52", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:24:10.091531+00:00", "role": null}, {"template_id": "ff165ae1-790a-4b59-a146-c5072b60dc74", "consent_type": "clinic_leave_anava", "version": 1, "title": "Partner Clinic — Leave Anava Network Consent", "content": "We, the authorized representatives of [PARTNER_CLINIC_NAME], consent to the closure of our partnership with the Anava Clinic network operated by Mana Health Sciences Group. We acknowledge that all patient records must be transferred or archived before closure can be completed. We understand that data retention obligations continue after departure and that all records will remain in the Anava system in read-only status permanently.", "content_hash": "0eebee27839de0feafc0b1b7f49abf096bfa211424437db0f4fc8f83e3b5c444", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:24:10.091531+00:00", "role": null}, {"template_id": "7bbaadfa-3f23-48c9-a521-14dae8631f02", "consent_type": "staff_onboarding", "version": 1, "title": "Staff Onboarding Consent", "content": "I, the undersigned staff member, consent to joining [CLINIC_NAME] as [ROLE]. I acknowledge receipt of the staff handbook and code of conduct. I understand my responsibilities regarding patient confidentiality, data protection, and clinical protocols as defined by Anava Clinic and Mana Health Sciences Group. I consent to the storage of my professional credentials and employment records in the Anava platform.", "content_hash": "5146a47104bc4351ab98d029f4f254f1946a997673e18f3fb9f4828b7d890141", "effective_date": null, "expiry_date": null, "is_active": false, "created_at": "2026-07-06T12:24:10.091531+00:00", "role": null}, {"template_id": "f6220371-f120-4e25-ab52-826eca35e282", "consent_type": "staff_onboarding", "version": 1, "title": "Doctor Onboarding Consent", "content": "I, the undersigned Doctor, consent to joining [CLINIC_NAME]. I acknowledge receipt of the staff handbook and code of conduct. I understand my responsibilities regarding patient confidentiality, data protection, clinical protocols, and my authority to authorize assessment protocols and treatment plans as defined by Anava Clinic and Mana Health Sciences Group. I consent to the storage of my professional credentials (license, specialization, hospital affiliation) and employment records in the Anava platform.", "content_hash": "bd1ce59e6cd8b4fc1c1f746a501fc99b6b6797af16c34208fd78cc643c2a6bd8", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:25:04.675521+00:00", "role": "doctor"}, {"template_id": "6fb185bb-d4f1-4ee9-8603-144e19eb4aa1", "consent_type": "staff_onboarding", "version": 1, "title": "Clinical Assistant Onboarding Consent", "content": "I, the undersigned Clinical Assistant, consent to joining [CLINIC_NAME]. I acknowledge receipt of the staff handbook and code of conduct. I understand my responsibilities regarding patient confidentiality, data protection, and my role in designing assessment protocols and administering Session 1/3 diagnostics as defined by Anava Clinic and Mana Health Sciences Group. I consent to the storage of my professional credentials and employment records in the Anava platform.", "content_hash": "96092f2a40d98ceac90940d6dbe0700b5db0e433af3e4d095108f6f78ee6ccff", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:25:04.675521+00:00", "role": "clinical_assistant"}, {"template_id": "f3e54ef9-c1b6-4ef7-ae8d-f63c995be2ea", "consent_type": "staff_onboarding", "version": 1, "title": "Receptionist Onboarding Consent", "content": "I, the undersigned Receptionist, consent to joining [CLINIC_NAME]. I acknowledge receipt of the staff handbook and code of conduct. I understand my responsibilities regarding patient registration, appointment scheduling, witnessing patient consent, and data protection as defined by Anava Clinic and Mana Health Sciences Group. I consent to the storage of my employment records in the Anava platform.", "content_hash": "6c52c9cb15515ae1cbdba87de0695a8df2a3f328d298a32bb4826f0878f06459", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:25:04.675521+00:00", "role": "receptionist"}, {"template_id": "f4b3d632-7c3d-4adc-bb79-08320f96d815", "consent_type": "staff_onboarding", "version": 1, "title": "Clinic Admin Onboarding Consent", "content": "I, the undersigned Clinic Admin, consent to joining [CLINIC_NAME]. I acknowledge receipt of the staff handbook and code of conduct. I understand my responsibilities regarding daily clinic operations, staff requests, payment waivers, and data protection as defined by Anava Clinic and Mana Health Sciences Group. I consent to the storage of my professional credentials and employment records in the Anava platform.", "content_hash": "105ce46aa7f07d9e81ebd9485a5a848deb6112364313a6e275938e72da83924a", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:25:04.675521+00:00", "role": "clinic_admin"}, {"template_id": "fd03377f-276b-4f99-8ae2-455a815824e4", "consent_type": "staff_onboarding", "version": 1, "title": "Regional Admin Onboarding Consent", "content": "I, the undersigned Regional Admin, consent to joining Anava Clinic for my assigned region. I acknowledge receipt of the staff handbook and code of conduct. I understand my responsibilities regarding staff approval, main-branch stock management, and regional oversight as defined by Anava Clinic and Mana Health Sciences Group. I consent to the storage of my professional credentials and employment records in the Anava platform.", "content_hash": "0879af068bb9b4dc64bc55b020b43cbbb7ab17ae5f4c9049c5bb8f24b936568c", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:25:04.675521+00:00", "role": "regional_admin"}, {"template_id": "2b4a639c-fe21-4d5b-bcdc-02627f3494b8", "consent_type": "staff_onboarding", "version": 1, "title": "Super Admin Onboarding Consent", "content": "I, the undersigned Super Admin, consent to joining Anava Clinic with system-wide access. I acknowledge receipt of the staff handbook and code of conduct. I understand my responsibilities regarding system-wide administration, central stock, and platform bootstrap as defined by Anava Clinic and Mana Health Sciences Group. I consent to the storage of my professional credentials and employment records in the Anava platform.", "content_hash": "e3da3418421cc87b7a4760bef3a092fb6bd3d53d1b2c6c85802ce1f69700b102", "effective_date": null, "expiry_date": null, "is_active": true, "created_at": "2026-07-06T12:25:04.675521+00:00", "role": "super_admin"}]$json$::jsonb)
ON CONFLICT DO NOTHING;

COMMIT;
